/** SafeMeal AI triage: deterministic signal analysis + a small supervised NLP classifier.
 * This is a decision-support model trained from synthetic examples, not a lab test. */
const TRAIN=[
 ['sản phẩm bị mốc có đốm trắng mùi hôi lạ','spoilage'],['rau bị thối nhũn có dấu hiệu mốc','spoilage'],['thịt chuyển màu xanh bốc mùi','spoilage'],['sữa chua bị phồng nắp và có mùi chua thối','spoilage'],['hàng hóa có nấm mốc lên men bất thường','spoilage'],['nấm xuất hiện trên bao bì thực phẩm','spoilage'],['sản phẩm biến chất thịt nhớt bốc mùi khó chịu','spoilage'],
 ['nhiệt độ bảo quản vượt ngưỡng quá nóng','coldchain'],['xe lạnh không đủ nhiệt độ bị mất điện','coldchain'],['tủ mát không hoạt động lạnh đứt chuỗi','coldchain'],['sensor ghi 15 độ c trong vận chuyển','coldchain'],['bảo quản không đúng tiêu chuẩn nhiệt độ','coldchain'],['đông lạnh bị rã đông trong giao hàng','coldchain'],['hàng bị để ngoài trời nắng quá lâu','coldchain'],
 ['mã qr quét không ra nguồn gốc','identity'],['tem niêm phong bị rách nghi bị tráo','identity'],['mã lô in khác mã qr trên bao bì','identity'],['nghi ngờ hàng giả không đúng nhà cung cấp','identity'],['bao bì nhãn mác có dấu hiệu làm giả','identity'],['nhãn sản phẩm sai ngày sản xuất','identity'],['hóa đơn không khớp với mã kiểm định','identity'],
 ['ăn vào bị nổi mẩn ngứa dị ứng hải sản','allergy'],['người dùng bị dị ứng sau khi ăn','allergy'],['sản phẩm thiếu cảnh báo đậu phộng','allergy'],['nghi sốc phản vệ sau bữa ăn','allergy'],['thành phần không ghi rõ gluten sữa trứng','allergy'],['khách bị mẩn đỏ và khó thở sau ăn','allergy'],['nhãn thiếu thông tin chất gây dị ứng','allergy'],
 ['bao bì bị rách thủng khi vận chuyển','damage'],['chai nhựa bị bể nắp chai bị méo','damage'],['đóng gói hỏng vỏ hộp bị móp','damage'],['thùng hàng bị dập nát trong kho','damage'],['vỡ bao bì khi vận chuyển đến quầy','damage'],['seal bị hở lọ không kín','damage'],['màng bọc thực phẩm bị bung','damage']
];
const LABELS={spoilage:'Nghi ngờ hư hỏng/mốc',coldchain:'Gián đoạn chuỗi lạnh',identity:'Sai tem/mã hoặc nhận diện',allergy:'Dị ứng/thành phần',damage:'Bao bì/niêm phong'};
const WORDS=s=>String(s||'').toLowerCase().normalize('NFC').replace(/[^\p{L}\p{N}°]+/gu,' ').trim().split(/\s+/).filter(x=>x.length>1);
const clamp=(v,lo,hi)=>Math.max(lo,Math.min(hi,v));
export function classifyText(input){const tokens=WORDS(input);if(tokens.length<3)return {label:'unknown',title:'Chưa đủ dữ liệu',confidence:0,probabilities:{},method:'Multinomial Naive Bayes (35 câu mẫu giả lập)'};
 const total={}, vocab=new Set(),models={};for(const label of Object.keys(LABELS)){models[label]={tokens:0,counts:new Map(),samples:0}}
 for(const [phrase,label] of TRAIN){const m=models[label];m.samples++;for(const t of WORDS(phrase)){vocab.add(t);m.tokens++;m.counts.set(t,(m.counts.get(t)||0)+1)}}
 const totalSamples=TRAIN.length, scores={};for(const [label,m] of Object.entries(models)){let log=Math.log(m.samples/totalSamples);for(const t of tokens)log+=Math.log(((m.counts.get(t)||0)+1)/(m.tokens+vocab.size));scores[label]=log}
 const highest=Math.max(...Object.values(scores));const normal=Object.fromEntries(Object.entries(scores).map(([k,v])=>[k,Math.exp(v-highest)]));const denominator=Object.values(normal).reduce((a,b)=>a+b,0);const probabilities=Object.fromEntries(Object.entries(normal).map(([k,v])=>[k,+(v/denominator).toFixed(4)]));const label=Object.entries(probabilities).sort((a,b)=>b[1]-a[1])[0][0];return {label,title:LABELS[label],confidence:probabilities[label],probabilities,method:'Multinomial Naive Bayes (35 câu mẫu giả lập)',warning:'Điểm chỉ dùng sắp xếp phản ánh, không phải dự đoán bệnh hay chất lượng thực phẩm.'}}
const median=arr=>{const s=[...arr].sort((a,b)=>a-b),n=s.length;return n%2?s[Math.floor(n/2)]:(s[n/2-1]+s[n/2])/2};
export function parseTemperature(input){const rows=String(input||'').trim().split(/\r?\n/).map(s=>s.trim()).filter(Boolean);const points=[];for(const row of rows){const parts=row.split(/[;,\t]/).map(s=>s.trim());if(parts.length<2)continue;const temp=Number(parts.at(-1).replace(/°c$/i,''));if(!Number.isFinite(temp))continue;const stamp=parts.slice(0,-1).join(',');if(stamp.toLowerCase().includes('time')||stamp.toLowerCase().includes('giờ'))continue;points.push({time:stamp,temp})}return points}
export function analyzeColdChain(points,threshold){const data=Array.isArray(points)?points:parseTemperature(points);const limit=Number(threshold);if(!Number.isFinite(limit)||data.length<4)throw Error('Cần ít nhất 4 mốc nhiệt độ (thời điểm,nhiệt độ) và ngưỡng hợp lệ.');if(data.length>1500)throw Error('Tối đa 1500 điểm đo cho demo.');if(data.some(x=>!Number.isFinite(Number(x.temp))))throw Error('Nhiệt độ không hợp lệ.');const vals=data.map(x=>Number(x.temp));const med=median(vals),mad=median(vals.map(x=>Math.abs(x-med)));const robust=vals.map(x=>Math.abs(x-med)/(1.4826*Math.max(mad,.35)));const flagged=vals.map((v,i)=>({i,time:data[i].time,temp:v,above:v>limit,outlier:robust[i]>3.5})).filter(x=>x.above||x.outlier);let longest=0,run=0;for(const v of vals){run=v>limit?run+1:0;longest=Math.max(longest,run)}const exceed=vals.filter(v=>v>limit).length;const max=Math.max(...vals),min=Math.min(...vals);const excursion=exceed?max-limit:0;const anomalous=robust.filter(x=>x>3.5).length;
 // The risk score is a hand-designed heuristic, not a calibrated ML probability.
 const score=Math.round(clamp(10+(exceed/vals.length)*48+Math.min(25,Math.max(0,excursion)*5)+Math.min(17,Math.max(0,longest-1)*6)+Math.min(10,anomalous*2),0,100));const level=exceed>=2||excursion>2||score>=65?'high':exceed||anomalous?'medium':'low';return {count:vals.length,max,min,median:+med.toFixed(2),mad:+mad.toFixed(2),exceed,exceedPct:+(100*exceed/vals.length).toFixed(1),longest,anomalous,flagged,values:vals,threshold:limit,riskScore:score,level,method:'Robust MAD + phát hiện vượt ngưỡng liên tiếp; điểm rủi ro theo quy tắc',disclaimer:'Không chứng minh an toàn thực phẩm. Muốn định lượng thời gian vi phạm cần timestamp và chu kỳ lấy mẫu chuẩn.'}}
export function visualSimilarity(a,b){if(!a?.length||a.length!==b?.length)throw Error('Vector đặc trưng không tương thích');let dot=0,aa=0,bb=0;for(let i=0;i<a.length;i++){const x=Number(a[i]),y=Number(b[i]);dot+=x*y;aa+=x*x;bb+=y*y}return aa&&bb?clamp(dot/Math.sqrt(aa*bb),-1,1):0}
export function ocrEvidence(text,expectedLot='',expectedProduct=''){const cleaned=String(text||'').normalize('NFC').replace(/\s+/g,' ');const dates=[...cleaned.matchAll(/\b(\d{2})[\/.-](\d{2})[\/.-](\d{4})\b/g)].map(m=>`${m[3]}-${m[2]}-${m[1]}`);const lotFound=[...cleaned.matchAll(/\bL\s?\d{3,6}\b/gi)].map(x=>x[0].replace(/\s/g,'').toUpperCase());const expected=String(expectedLot).trim().toUpperCase();const matched=expected&&lotFound.length?lotFound.includes(expected):null;return {text:cleaned.slice(0,1800),foundLots:[...new Set(lotFound)],dates,lotMatch:matched,productMention:expectedProduct?cleaned.toLocaleLowerCase('vi').includes(String(expectedProduct).toLocaleLowerCase('vi').slice(0,12)):null,warning:'OCR có thể đọc sai; cần đối chiếu bằng mắt trước khi phê duyệt.'}}
export function fuseEvidence({coldchain=null,vision=null,ocr=null,nlp=null}={}){const lines=[],weights=[];if(coldchain){weights.push(coldchain.riskScore);lines.push(`Chuỗi lạnh: ${coldchain.exceed}/${coldchain.count} mẫu vượt ${coldchain.threshold}°C; ${coldchain.level==='high'?'cần rà soát ngay':'theo dõi'}.`)}if(vision?.similarity!=null){const risk=vision.similarity<.75?70:vision.similarity<.88?40:10;weights.push(risk);lines.push(`Tương đồng đặc trưng ảnh: ${(vision.similarity*100).toFixed(1)}% (không phải bằng chứng hàng thật).`)}if(ocr){if(ocr.lotMatch===false){weights.push(85);lines.push('OCR phát hiện mã lô trên bao bì không khớp hồ sơ.') }else if(ocr.lotMatch===true)lines.push('OCR tìm thấy mã lô dự kiến; vẫn cần đối chiếu bản gốc.')}if(nlp&&nlp.confidence>.45){weights.push(['allergy','spoilage'].includes(nlp.label)?70:45);lines.push(`Phản ánh văn bản thuộc nhóm ${nlp.title}, độ phù hợp mô hình ${(nlp.confidence*100).toFixed(0)}%.`)}const score=weights.length?Math.round(Math.max(...weights)):null;return {score,level:score==null?'unknown':score>=60?'review-required':score>=30?'warning':'low',lines,decision:'Chỉ người kiểm định có quyền phê duyệt. AI không thay thế xét nghiệm hay kiểm định tại hiện trường.',modelVersion:'SafeMeal-AI-Triage-v1',missing:weights.length===0}}
